-- Catálogo de alimentos: Tablas Peruanas de Composición de Alimentos (INS/CENAN, 2017).
-- Extraído del PDF oficial. Valores por 100 g de porción comestible, tal como los publica la fuente.
-- 11 grupos, 884 alimentos. La columna source lleva el código TPCA de cada fila.

-- Algunos alimentos no reportan todos los macronutrientes ('•' en la tabla original).
-- Se guardan con 0 y se marcan, en vez de descartarlos: el atún en conserva no reporta
-- carbohidratos, pero seguir sin atún en el catálogo sería peor.
alter table public.foods add column if not exists data_incomplete boolean not null default false;

comment on column public.foods.data_incomplete is
  'true cuando la TPCA no reporta alguno de los macronutrientes; ese valor se guarda como 0.';

-- Los 5 alimentos de la semilla provisional quedan reemplazados por sus filas reales.
delete from public.foods where slug in (
  'arroz-blanco-cocido', 'quinua', 'pan-frances', 'fideos', 'avena'
);

on conflict (slug) do update set
  name = excluded.name, category = excluded.category,
  energy_kcal = excluded.energy_kcal, protein_g = excluded.protein_g,
  carbs_g = excluded.carbs_g, fat_g = excluded.fat_g,
  source = excluded.source, data_incomplete = excluded.data_incomplete,
  is_published = excluded.is_published, updated_at = now();

-- Porciones caseras. NO provienen de la TPCA: son equivalencias domésticas estimadas.
select f.id, p.label, p.grams, p.is_default, p.sort_order
from public.foods f join (values
  ('a2-arroz-pilado-o-pulido-cocido', '1 taza', 150.0, true, 10),
  ('a2-arroz-pilado-o-pulido-cocido', '1 cucharon', 100.0, false, 20),
  ('a5-avena-envasada', '1/2 taza en hojuelas', 40.0, true, 10),
  ('a22-fideo-tallarin-crudo-fortificado-con-hierro', '1 taza cocida', 140.0, true, 10),
  ('a49-pan-frances-fortificado-con-hierro', '1 unidad', 55.0, true, 10),
  ('a54-quinua', '1 taza cocida', 185.0, true, 10),
  ('c42-manzana-nacional', '1 unidad', 150.0, true, 10),
  ('c71-platano-de-seda', '1 unidad', 120.0, true, 10),
  ('d9-aceite-vegetal-de-soya', '1 cucharada', 14.0, true, 10),
  ('e19-pescado-atun-en-conserva', '1 lata escurrida', 120.0, true, 10),
  ('f26-pollo-carne-pulpa', '1 presa', 150.0, true, 10),
  ('f82-pollo-pechuga-cocida-de', '1 filete', 120.0, true, 10),
  ('g7-leche-evaporada-entera', '1 taza', 240.0, true, 10),
  ('g7-leche-evaporada-entera', '1 tarro', 400.0, false, 20),
  ('g14-queso-fresco-de-vaca', '1 tajada', 40.0, true, 10),
  ('j3-huevo-de-gallina-entero-sancochado-en-agua', '1 unidad', 50.0, true, 10),
  ('t52-lentejas-chicas', '1 taza cocida', 200.0, true, 10),
  ('u3-camote-amarillo-sin-cascara', '1 unidad mediana', 130.0, true, 10),
  ('u19-papa-blanca', '1 unidad mediana', 150.0, true, 10)
) as p(slug, label, grams, is_default, sort_order) on p.slug = f.slug
on conflict (food_id, label) do update set
  grams = excluded.grams, is_default = excluded.is_default, sort_order = excluded.sort_order;
